import React from 'react';
import { useNavigate } from 'react-router-dom';
import './BadgesPage.css';

export default function BadgesPage() {
  const navigate = useNavigate();

  const goToLogin = () => {
    navigate('/login');
  };

  return (
    <div className="badges-page">
      <h2 className="title">Achievement Badges</h2>

      <div className="badge-grid">

        <div className="badge-card">
          <img src="/badges/volunteer1.png" alt="Volunteer Starter" />
          <h3>Volunteer Starter</h3>
          <p>Awarded for registering as a volunteer.</p>
          <button className="badge-btn" onClick={goToLogin}>Volunteer Now</button>
        </div>

        <div className="badge-card">
          <img src="/badges/donation1.png" alt="Donation Supporter" />
          <h3>Donation Supporter</h3>
          <p>Awarded for making your first donation.</p>
          <button className="badge-btn" onClick={goToLogin}>Donate Now</button>
        </div>

        <div className="badge-card">
          <img src="/badges/helpinghands.png" alt="Helping Hands" />
          <h3>Helping Hands</h3>
          <p>Given to members who actively help NGOs.</p>
          <button className="badge-btn" onClick={goToLogin}>Volunteer Now</button>
        </div>

      </div>
    </div>
  );
}
